  "c93599951.lua":"--沈黙の邪悪霊\n--Dark Spirit of the Silent\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--Activate\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_ACTIVATE)\n\te1:SetProperty(EFFECT_FLAG_CARD_TARGET)\n\te1:SetCode(EVENT_FREE_CHAIN)\n\te1:SetCondition(s.condition)\n\te1:SetTarget(s.target)\n\te1:SetOperation(s.activate)\n\tc:RegisterEffect(e1)\nend\nfunction s.condition(e,tp,eg,ep,ev,re,r,rp)\n\treturn Duel.IsTurnPlayer(1-tp)\nend\nfunction s.target(e,tp,eg,ep,ev,re,r,rp,chk,chkc)\n\tif chkc then return false end\n\tlocal a=Duel.GetAttacker()\n\tif chk==0 then return a and a:IsCanBeEffectTarget(e) and Duel.IsExistingTarget(Card.IsFaceup,tp,0,LOCATION_MZONE,1,a) end\n\tDuel.SetTargetCard(a)\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_TARGET)\n\tlocal g=Duel.SelectTarget(tp,Card.IsFaceup,tp,0,LOCATION_MZONE,1,1,a)\n\te:SetLabelObject(g:GetFirst())\nend\nfunction s.activate(e,tp,eg,ep,ev,re,r,rp)\n\tlocal tc=e:GetLabelObject()\n\tif Duel.NegateAttack() and tc:IsRelateToEffect(e) and tc:IsFaceup() then\n\t\tif tc:IsDefensePos() then\n\t\t\tDuel.ChangePosition(tc,POS_FACEUP_ATTACK)\n\t\tend\n\t\tif tc:CanAttack() and not tc:IsImmuneToEffect(e) then\n\t\t\tDuel.BreakEffect()\n\t\t\tDuel.CalculateDamage(tc,Duel.GetAttackTarget())\n\t\tend\n\tend\nend",
  "official/c93671934.lua":"--士気高揚\n--Morale Boost\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--Activate\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_ACTIVATE)\n\te1:SetCode(EVENT_FREE_CHAIN)\n\tc:RegisterEffect(e1)\n\t--recover\n\tlocal e2=Effect.CreateEffect(c)\n\te2:SetCategory(CATEGORY_RECOVER)\n\te2:SetType(EFFECT_TYPE_FIELD+EFFECT_TYPE_TRIGGER_F)\n\te2:SetCode(EVENT_EQUIP)\n\te2:SetRange(LOCATION_SZONE)\n\te2:SetCondition(s.reccon)\n\te2:SetTarget(s.rectg)\n\te2:SetOperation(s.recop)\n\tc:RegisterEffect(e2)\n\t--damage\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetCategory(CATEGORY_DAMAGE)\n\te3:SetType(EFFECT_TYPE_FIELD+EFFECT_TYPE_TRIGGER_F)\n\te3:SetCode(EVENT_LEAVE_FIELD)\n\te3:SetRange(LOCATION_SZONE)\n\te3:SetCondition(s.damcon)\n\te3:SetTarget(s.damtg)\n\te3:SetOperation(s.damop)\n\tc:RegisterEffect(e3)\nend\nfunction s.reccon(e,tp,eg,ep,ev,re,r,rp)\n\te:SetLabel(eg:GetFirst():GetControler())\n\treturn true\nend\nfunction s.rectg(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return true end\n\tDuel.SetOperationInfo(0,CATEGORY_RECOVER,nil,0,e:GetLabel(),1000)\nend\nfunction s.recop(e,tp,eg,ep,ev,re,r,rp)\n\tDuel.Recover(e:GetLabel(),1000,REASON_EFFECT)\nend\nfunction s.filter(c)\n\treturn c:GetEquipTarget()~=nil or c:IsReason(REASON_LOST_TARGET)\nend\nfunction s.damcon(e,tp,eg,ep,ev,re,r,rp)\n\tlocal g=eg:Filter(s.filter,nil)\n\tif #g==0 then return false end\n\tlocal flag=0\n\tif g:IsExists(Card.IsControler,1,nil,0) then flag=flag+1 end\n\tif g:IsExists(Card.IsControler,1,nil,1) then flag=flag+2 end\n\te:SetLabel(({0,1,PLAYER_ALL})[flag])\n\treturn true\nend\nfunction s.damtg(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return true end\n\tDuel.SetOperationInfo(0,CATEGORY_DAMAGE,nil,0,e:GetLabel(),1000)\nend\nfunction s.damop(e,tp,eg,ep,ev,re,r,rp)\n\tif e:GetLabel()~=1-tp then\n\t\tDuel.Damage(tp,1000,REASON_EFFECT,true)\n\tend\n\tif e:GetLabel()~=tp then\n\t\tDuel.Damage(1-tp,1000,REASON_EFFECT,true)\n\tend\n\tDuel.RDComplete()\nend",
